from taf.internal.robot_typecasts import time_to_seconds
from taf.gnb.oam.coam.admin.legacy.ute_admin.util import ProvidedContent
from ..util import wrap_result


class CertificateManagmentInterface(object):

    def get_certificate_file(self, fingerprint, target_file_name, timeout=60):
        """Get certificate file.

        :param string fingerprint: Unique sign of certificate.
        :param string target_file_name: target certificate filename.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        str(fingerprint)
        timeout = time_to_seconds(timeout)
        self._api_client.execute_customer_procedure("getCertFile", {"fingerPrint": fingerprint}, timeout, output_file_name=target_file_name)

    def get_certificate_details(self, fingerprint, timeout=60):
        """Get certificate details.

        :param string fingerprint: Unique sign of certificate.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        str(fingerprint)
        timeout = time_to_seconds(timeout)
        return self._api_client.execute_customer_procedure(
            "getCertDetails", {"fingerPrint": fingerprint}, timeout).get(ProvidedContent.request_message)

    @wrap_result
    def get_certificate_list(self, type, timeout=60):
        """Get certificate list.

        :param string type: Certificate type (BTS, TA, CA, RA, Vendor or All)
        :param float timeout: Time to wait for positive procedure result.
        
        """
        str(type)

        timeout = time_to_seconds(timeout)
        return self._api_client.execute_customer_procedure(
            "getCertList", {"type": type}, timeout).get(ProvidedContent.request_message)

    def get_certificate_revocation_list(self, timeout=60):
        """Get certificate revocation list.

        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        return self._api_client.execute_customer_procedure(
            "certGetRevocationList", {}, timeout).get(ProvidedContent.request_message)

    def cmp_update_key(self, timeout=60):
        """CMP update key.

        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        self._api_client.execute_customer_procedure("certCmpKeyUpdate", {}, timeout)

    def install_certificate(self, cert_file, cert_type, cert_format, password=None, timeout=60):
        """Install certificate.

        :param string cert_file: Certificate file path.
        :param string cert_type: Certificate type (BtsTrustChain or AdditionalCa)
        :param string cert_format: Certificate format (PEM, P12 or DER)
        :param string password: Certificate password.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        str(cert_file)
        str(cert_type)
        str(cert_format)

        timeout = time_to_seconds(timeout)

        parameters = {"fileType": cert_type, "fileFormat": cert_format}
        if password:
            parameters["password"] = password
        self._api_client.execute_customer_procedure("installCert", parameters, timeout, input_file_name=cert_file)

    def delete_certificate(self, fingerprint, timeout=60):
        """Delete certificate.

        :param string fingerprint: Unique sign of certificate.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        str(fingerprint)

        timeout = time_to_seconds(timeout)
        self._api_client.execute_customer_procedure("deleteCert", {"fingerPrint": fingerprint}, timeout)

    def restore_vendor_certificate(self, timeout=60):
        """Restore vendor certificate.

        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        self._api_client.execute_customer_procedure("certRestoreVendor", {}, timeout)

    def update_certificate_revocation_list(self, timeout=60):
        """Update certificate revocation list.

        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        self._api_client.execute_customer_procedure("certUpdateRevocationList", {}, timeout)

    def set_certificate_automatic_managment(self, reference_number, preshared_key, timeout=60):
        """Set certificate automatic managment.

        :param string reference_number: Reference number
        :param string preshared_key: Pre-shared key.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        str(reference_number)
        str(preshared_key)

        timeout = time_to_seconds(timeout)
        self._api_client.execute_customer_procedure(
            "certAutomaticManagement", {"referenceNumber": reference_number, "preSharedKey": preshared_key}, timeout)
